package com.mannvaasam.controller;import org.springframework.web.bind.annotation.*;import org.springframework.http.*;import java.util.*;@RestControllerAdvice public class GlobalExceptionHandler{@ExceptionHandler(IllegalArgumentException.class)ResponseEntity<?> bad(IllegalArgumentException e){return ResponseEntity.badRequest().body(Map.of("error",e.getMessage()));}@ExceptionHandler(Exception.class)ResponseEntity<?> error(Exception e){return ResponseEntity.internalServerError().body(Map.of("error","Unexpected server error"));}}